// 1D DP（滾動陣列）：prev 保存左上角 dp[i-1][j-1]
// 時間複雜度: O(m·n)，空間複雜度: O(n)
int longestCommonSubsequence(char* text1, char* text2) {
    int m = strlen(text1), n = strlen(text2);
    int* dp = calloc(n + 1, sizeof(int));
    for (int i = 1; i <= m; i++) {
        int prev = 0;                         // dp[i-1][0]
        for (int j = 1; j <= n; j++) {
            int tmp = dp[j];                  // dp[i-1][j]
            if (text1[i - 1] == text2[j - 1]) dp[j] = prev + 1;
            else if (dp[j - 1] > dp[j]) dp[j] = dp[j - 1];
            prev = tmp;
        }
    }
    int ans = dp[n];
    free(dp);
    return ans;
}

